#!/usr/bin/env python3
"""A small persistent HTTP key-value service using only the standard library."""

from __future__ import annotations

import argparse
import json
import math
import os
import signal
import sys
import tempfile
import threading
import time
from http import HTTPStatus
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from typing import Any
from urllib.parse import unquote_to_bytes, urlsplit


MAX_BODY = 1024 * 1024


class StoreError(Exception):
    pass


class PersistentStore:
    def __init__(self, path: Path):
        self.path = path
        self.lock = threading.RLock()
        self.entries: dict[str, dict[str, Any]] = {}
        self._load()

    def _load(self) -> None:
        try:
            if self.path.exists():
                with self.path.open("r", encoding="utf-8") as stream:
                    raw = json.load(stream)
                if not isinstance(raw, dict) or raw.get("version") != 1 or not isinstance(raw.get("entries"), dict):
                    raise StoreError("invalid data-file format")
                now = time.time()
                for key, entry in raw["entries"].items():
                    if not isinstance(key, str) or not isinstance(entry, dict) or "value" not in entry:
                        raise StoreError("invalid entry in data file")
                    expires = entry.get("expires_at")
                    if expires is not None and (not isinstance(expires, (int, float)) or isinstance(expires, bool) or not math.isfinite(expires)):
                        raise StoreError("invalid expiry in data file")
                    if expires is None or expires > now:
                        self.entries[key] = {"value": entry["value"], "expires_at": expires}
                if len(self.entries) != len(raw["entries"]):
                    self._persist(self.entries)
        except StoreError:
            raise
        except (OSError, ValueError, TypeError, json.JSONDecodeError) as exc:
            raise StoreError(f"cannot load data file: {exc}") from exc

    def _persist(self, entries: dict[str, dict[str, Any]]) -> None:
        parent = self.path.parent
        temp_name: str | None = None
        try:
            parent.mkdir(parents=True, exist_ok=True)
            payload = {"version": 1, "entries": entries}
            with tempfile.NamedTemporaryFile(
                mode="w", encoding="utf-8", dir=parent, prefix=f".{self.path.name}.", delete=False
            ) as stream:
                temp_name = stream.name
                json.dump(payload, stream, ensure_ascii=False, separators=(",", ":"), allow_nan=False)
                stream.write("\n")
                stream.flush()
                os.fsync(stream.fileno())
            os.replace(temp_name, self.path)
            temp_name = None
            try:
                directory_fd = os.open(parent, os.O_RDONLY)
                try:
                    os.fsync(directory_fd)
                finally:
                    os.close(directory_fd)
            except OSError:
                pass
        except (OSError, ValueError, TypeError) as exc:
            raise StoreError(f"cannot persist data: {exc}") from exc
        finally:
            if temp_name is not None:
                try:
                    os.unlink(temp_name)
                except OSError:
                    pass

    @staticmethod
    def _live(entries: dict[str, dict[str, Any]], now: float) -> dict[str, dict[str, Any]]:
        return {
            key: entry
            for key, entry in entries.items()
            if entry["expires_at"] is None or entry["expires_at"] > now
        }

    def _prune(self) -> None:
        live = self._live(self.entries, time.time())
        if len(live) != len(self.entries):
            self._persist(live)
            self.entries = live

    def put(self, key: str, value: Any, ttl: float | None) -> bool:
        with self.lock:
            self._prune()
            created = key not in self.entries
            updated = dict(self.entries)
            updated[key] = {
                "value": value,
                "expires_at": None if ttl is None else time.time() + ttl,
            }
            self._persist(updated)
            self.entries = updated
            return created

    def get(self, key: str) -> tuple[bool, Any]:
        with self.lock:
            self._prune()
            entry = self.entries.get(key)
            return (False, None) if entry is None else (True, entry["value"])

    def delete(self, key: str) -> bool:
        with self.lock:
            self._prune()
            if key not in self.entries:
                return False
            updated = dict(self.entries)
            del updated[key]
            self._persist(updated)
            self.entries = updated
            return True

    def keys(self) -> list[str]:
        with self.lock:
            self._prune()
            return sorted(self.entries)


class Server(ThreadingHTTPServer):
    daemon_threads = True
    allow_reuse_address = True

